import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"Thinking in Video: Can Video Generators Really Reason About the Real World?","description":"","frontmatter":{"title":"Thinking in Video: Can Video Generators Really Reason About the Real World?","arxiv":"2607.17523","date":"2026-07-20","authors":"Yongheng Zhang, Guang Yang, Ruihan Hou, Qiguang Chen, Ziang Liu, Xiaolong Liu, Manman Zhang, Yanchao Hao, Zheng Wei, Hao Wu, Libo Qin, Peishan Dai, Yinghui Li, Di Yin, Xing Sun","categories":"cs.CV, cs.AI, cs.CL","topics":"世界模型, 视频生成评测, 因果推理","outline":[2,2]},"headers":[],"relativePath":"papers/2607.17523.md","filePath":"papers/2607.17523.md","lastUpdated":null}'),e={name:"papers/2607.17523.md"};function l(i,s,m,r,c,g){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="thinking-in-video-can-video-generators-really-reason-about-the-real-world" tabindex="-1">Thinking in Video: Can Video Generators Really Reason About the Real World? <a class="header-anchor" href="#thinking-in-video-can-video-generators-really-reason-about-the-real-world" aria-label="Permalink to &quot;Thinking in Video: Can Video Generators Really Reason About the Real World?&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2607.17523" target="_blank" rel="noreferrer">2607.17523</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-07-20</td></tr><tr><td><strong>作者</strong></td><td>Yongheng Zhang, Guang Yang, Ruihan Hou, Qiguang Chen, Ziang Liu, Xiaolong Liu, Manman Zhang, Yanchao Hao, Zheng Wei, Hao Wu, Libo Qin, Peishan Dai, Yinghui Li, Di Yin, Xing Sun</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI, cs.CL</td></tr><tr><td><strong>一句话</strong></td><td>用 Flatten Temporal Video 把视频问答压成一张静态图喂给只能吃图的视频生成器，同时考它&quot;能否说清因果&quot;和&quot;能否把因果画出来&quot;，从而把感知与预测拆开量化，暴露出 Perception-Prediction Gap。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频生成模型现在能合成分钟级高清片段，物体、运动、交互都连贯。这催生了一个超出视觉合成的主张：如果模型能从视觉条件 roll out 出合理的未来，它也许可以把视频当作推理的<strong>媒介</strong>。论文把这个方向命名为 <strong>Thinking in Video</strong>——模型不是用语言描述答案，而是在时间上构造、延展并审计一个视觉世界。</p><p>问题在于这个承诺一直没被验证过。一次令人信服的 rollout 不等于一次正确的推理过程。模型生成玻璃碎裂、物体下落、人做出反应，可能是因为它理解了因果条件，也可能只是记住了高频视觉关联。这个区别很要紧：推理要求反事实与因果有效性，不是逼真的续帧。</p><p>现有评测的结构性缺陷是把视觉保真度与语义逻辑<strong>分叉</strong>了。FVD、Inception Score 这类分布度量衡量平滑、真实、文本对齐，幻觉也可能得高分；静态多模态 benchmark 考符号或视觉问答，但不考会演化的视频式回答。于是当一个生成器&quot;看起来在推理&quot;时，我们无法判断它在模拟因果还是在模仿外观。作者把这个隐藏的裂缝命名为 <strong>Perception-Prediction Dissonance</strong>：模型可能知道结果，却渲染不出一致的像素。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文点名的前人工作分三类。</p><p><strong>分布式质量度量</strong>：FVD、Inception Score、VBench、EvalCrafter 这一族。它们已经能可靠地衡量时序平滑、视觉真实与文本对齐，对推动画质有明确作用。不够用的原因不是度量本身有问题，而是它们的设计目标就不包含&quot;生成的未来是否遵守场景力学&quot;——一个物理上不可能但视觉上光滑的续帧，在这些指标下没有惩罚。</p><p><strong>静态多模态 benchmark</strong>：T2V 类评测与 ViBe 这类幻觉度量考符号或视觉问答。它们的局限是评测对象是静态答案，而 Thinking in Video 的答案本身是一段演化的视频，无法直接套用。</p><p><strong>&quot;用视频思考&quot;的早期尝试</strong>：在数学、导航、具身问题求解上探索这一可能性的工作（tong2025thinking、yang2025reasoning、chow2025weave、chen2025tivibench、wei2025ggbench 等）。作者对这条线的批评是它们展示了可能性，但没有把&quot;理解因果情境&quot;与&quot;通过生成来行动&quot;这两件事分开考——因而无法定位失败发生在哪一端。</p><p>还有一个非常实际的障碍解释了为什么这个缺口一直没被填：<strong>视频生成模型不接受交织的视频—文本 prompt</strong>，大多数只能吃静态图。这直接导致无法用标准的视频问答协议去问它们&quot;这段视频里发生了什么因果&quot;。这是一个接口问题，不是能力问题，但它把整类评测挡在门外。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是一个怀疑：既然 rollout 的合理性可以来自记忆的视觉关联，那么&quot;生成得像&quot;就不能作为&quot;理解了&quot;的证据。要区分二者，必须找到一个不依赖生成质量的独立通道去问模型&quot;你认为原因是什么&quot;。</p><p>第二步撞上接口墙：视频生成器不能读交织的视频加文本。绕开的方式有两种，一是改模型（不可行，闭源模型只有 API），二是改<strong>输入表示</strong>。作者选了后者——如果模型只能读一张图，那就把视频和问题都压进一张图。</p><p>第三步是发现这个技巧同时解决了两件事。把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">70</span></span></span></span> 帧排成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">7</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span> 的空间网格，等于把时间序列变成视觉编码器可以直接访问的<strong>空间纹理</strong>；把问题栅格化成像素放在网格上方，等于让模型通过对指令与历史的联合注意来做推理。这就构造出一个可以直接判分的视觉 QA 任务，逼模型暴露它识别到的因果进程，而不是靠统计续帧蒙混过去。</p><p>第四步是设计生成侧的对偶考法。既然显式侧考&quot;能不能说&quot;，隐式侧就该考&quot;能不能画&quot;：在因果拐点处切开视频，前半段作条件，要求模型渲染出后果。两个通道的分数差，就是 Perception-Prediction Gap 的操作化定义。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>看起来合理的续帧既可能来自因果理解，也可能来自记住的视觉关联，光看生成结果分不开这两者。CGDJ 的做法是把同一个模型考两遍：一遍逼它把因果<strong>说出来</strong>（把视频和问题压成一张图，变成可直接判分的视觉 QA），一遍逼它把因果<strong>画出来</strong>（在因果拐点切开，只给前因，要求渲染后果）。两个分数之间的落差本身就是诊断量。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>显式因果感知数据</strong>。为对齐视频理解的评测标准，作者采用 Video-MME 的全部 900 段视频，覆盖短、中、长三种时长，分成六个域：Knowledge、Life Record、Sports Competition、Artistic Performance、Film &amp; Television、Multilingual。</p><p><strong>Flatten Temporal Video 变换</strong>分三步。第一步构时间网格：均匀采样 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">70</span></span></span></span> 帧，拼成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">7</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span> 的空间矩阵</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">grid</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.0682em;vertical-align:-1.2671em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8011em;"><span style="top:-1.8829em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">⨁</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">7</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2671em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size4">(</span></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8011em;"><span style="top:-1.8829em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">⨁</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">10</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2671em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3448em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5357em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mbin mtight">−</span><span class="mord mtight">1</span><span class="mclose mtight">)</span><span class="mord mtight">10</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3695em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4086em;"><span></span></span></span></span></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size4">)</span></span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">⊕</span></span></span></span> 表示空间拼接。第二步语义渲染：不用外部文本编码器，而是把文本查询 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord mathcal">Q</span></span></span></span> 直接用高保真栅格化函数变成像素表示 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">text</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，放在网格上方。第三步垂直整合并缩放到目标分辨率</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">composite</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">Resize</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1280</span><span class="mbin mtight">×</span><span class="mord mtight">720</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">(</span><span class="mopen">[</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">text</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">grid</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">]</span><span class="mclose delimcenter" style="top:0em;">)</span></span></span></span></span></span></p><p><strong>隐式生成预测数据</strong>。世界动力学被分成两大类以平衡刚性物理与人类行为：Natural Sciences（数据取自 The Sound of Water、Physion、Physics IQ Benchmark，细分为物理力学、自然与生命科学、材料与结构、场与能量）与 Sociology &amp; Humanities（数据取自 TLD Benchmark 车辆信号、Kinetics 人类动作、Ego4D 及部分网络视频，细分为交通行为、生活行为、职业角色行为、公共社交行为、体育活动行为）。最终 600 段高质量视频，两大类严格各 300 段。</p><p><strong>视频切分</strong>是这一支的关键设计。对每段视频，专家标注者人工定位 <strong>Causal Inflection Point</strong>——因果条件累积到触发不可逆事件或状态转移的那个确定边界。切点之前是 Input Video，作为提供因果上下文的视觉条件，并用 Gemini-3-Pro 生成详细语义描述与视频一同注入以辅助生成；切点之后是 Gold Video，作为记录了初始条件所实现结果的不可变参考。同样用 flatten 技巧：从 Input Video 均匀抽 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">7</span></span></span></span> 个关键帧水平拼接成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">motion</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2809em;vertical-align:-0.2997em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">⨁</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9812em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span></span></span></span>，构成一支连贯的&quot;视觉时间箭头&quot;，编码运动方向与动态状态变化。</p><p><strong>评测协议</strong>。显式侧两阶段全自动：先用 whisper-large-v2 转写生成视频的音轨——因为正确解法或推理步骤常常直接编码在音频里；再用 Gemini-3-Pro 作核心评判，输入是被测模型生成的视频、转写文本、原问题与选项、以及标准答案，判定生成视频是否呈现了标准答案蕴含的因果后果，输出 Correct / Incorrect，并用人工判断做过对齐验证。隐式侧是基于参考的比较式评测，Gemini-3-Pro 作&quot;视频质量审计员&quot;，把生成视频与 Gold Video 对比并严格遵循控制性文本描述，给出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>，涵盖三个维度：Semantic Alignment（物体/动作正确性）、Reference Consistency（相对真值的逻辑流）、Physical Validity（无闪烁与物理违规）。</p><p><strong>被测模型</strong>。视频生成器：开源的 Wan-2.2-14B 与 HunyuanVideo-1.5（本地推理），闭源的 Veo-3.1 与 Sora-2（官方 API，默认时长设置，最长 12 秒）。为建立性能天花板并验证 flatten 表示的有效性，还评了一组 MLLM：Qwen3-VL-Instruct 的 2B/4B/8B，以及 GPT-5 与 Gemini-3-Flash。MLLM 用两种输入协议：Setting A 直接吃原始视频 token 走自己的时序编码器，Setting B 吃与视频生成器完全相同的 flatten 网格图。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化集中在输入构造上，没有训练目标或理论推导，但这三个式子承担了实际的方法负担，值得说清。</p><p>时间网格 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">grid</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.3626em;vertical-align:-0.4086em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">⨁</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.954em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">7</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">⨁</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.954em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">10</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3448em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5357em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mbin mtight">−</span><span class="mord mtight">1</span><span class="mclose mtight">)</span><span class="mord mtight">10</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3695em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4086em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 做的事情是<strong>把时间维折进空间维</strong>。原本 70 帧需要模型有时序编码器才能读，折成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">7</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span> 网格后，任何单图编码器都能一次性看到全部 70 个时刻。代价是时间顺序从&quot;序列位置&quot;退化成&quot;阅读顺序约定&quot;（先行后列），模型必须自己推断这个约定。</p><p>垂直整合 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">composite</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">Resize</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1280</span><span class="mbin mtight">×</span><span class="mord mtight">720</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mopen">([</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">text</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">grid</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">])</span></span></span></span> 把栅格化的文本堆在网格上方，构造出一个&quot;视觉化的 prompt&quot;。这里有个隐含代价值得指出：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">Resize</span></span></span></span></span> 到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1280</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">720</span></span></span></span> 之后，每一帧在网格中大约只占 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">128</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">103</span></span></span></span> 像素，再扣掉文本占据的上方区域会更小。这个分辨率损失是 flatten 策略的固有成本。</p><p>运动条件 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">motion</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2809em;vertical-align:-0.2997em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">⨁</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9812em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span></span></span></span>（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">7</span></span></span></span>，水平拼接）与显式侧不同：它用更少的帧、单行排列，作者的说法是这样构成一支连贯的&quot;视觉时间箭头&quot;，编码运动的方向向量与动态时间状态变化。单行水平排列比二维网格更少歧义——从左到右就是时间流向，不需要模型推断换行规则。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>需要先说明：arXiv 的 HTML 版正文在实验章节的表格处渲染中断，Table 2 及之后的具体数值未能获取。以下只复述作者在摘要与正文中明确给出的文字结论，不复述任何未能核验的数字。</p><p><strong>问题一：视频生成器能不能识别并说清一段视频的因果结构？</strong> 设计是用 flatten 后的 900 段 Video-MME 样本，让生成器&quot;回答&quot;问题——它的回答形式是生成一段视频，由 Gemini-3-Pro 结合转写音频与标准答案判定是否呈现了正确的因果后果。为了把&quot;模型不会推理&quot;与&quot;flatten 表示丢了信息&quot;分开，作者用同一套 flatten 输入去考 MLLM（Setting B），并与 MLLM 直接吃原视频（Setting A）对比。答案：先进的闭源生成器如 Sora-2 与 Veo-3.1 表现出<strong>可测量的</strong>因果感知，而开源生成器在同一套 flatten 推理协议下几乎崩溃。</p><p><strong>问题二：显式感知差是否意味着生成出的未来也差？</strong> 设计是隐式侧的 600 段因果拐点切分数据，只给前因，要求渲染后果，与 Gold Video 比对打分。答案是否定的——开源模型即便显式因果感知接近于零，仍然能产出中等程度合理的因果续帧。作者把这个反差命名为 <strong>Perception-Prediction Gap</strong>：视觉行动可以超过显式因果理解。</p><p><strong>问题三：模型的因果知识以什么形式存在？</strong> 这是显式侧评测顺带暴露的现象。因为评判同时看视觉事件与转写音频，作者观察到 <strong>audio-visual misalignment</strong>——模型用语言把正确的因果逻辑说出来的可靠性，高于把它渲染出来的可靠性。</p><p>三个结论合起来对&quot;world simulator&quot;叙事构成挑战：当前系统能模仿世界动力学的一部分，最强的模型开始让感知与预测对齐，但稳健的视频式推理仍然需要因果知识与视觉计算之间更强的 grounding。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：把视频生成器当推理引擎的主张一直没被验证，因为看起来合理的 rollout 既可能来自因果理解也可能来自记住的视觉关联。CGDJ 用对偶评判把这两件事拆开：显式侧考模型能否读出因果结构，隐式侧考它能否渲染出因果后果。关键的工程使能技术是 Flatten Temporal Video，把 70 帧折成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">7</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span> 网格并把问题栅格化成像素堆在上方，让只能吃静态图的视频生成器也能被施加视觉 QA 协议。评测覆盖 900 段 Video-MME 视频（六域）与 600 段按人工标注的因果拐点切开的视频（自然科学与社会人文各 300），用 whisper 转写音轨加 Gemini-3-Pro 判定。结果显示开源模型在显式因果感知上接近崩溃却仍能生成中等合理的动力学，闭源模型对齐更好但仍有限，且模型说得比画得准。</p><p><strong>3 句话版</strong>：视频生成器&quot;看起来在推理&quot;，但没人分得清它是在模拟因果还是模仿外观。CGDJ 把同一个模型考两遍——说出因果与画出因果——用两者之差定义 Perception-Prediction Gap。测下来这个 gap 在开源模型上很大，闭源模型收窄但没消失。</p><p><strong>1 句话版</strong>：把&quot;能不能说清因果&quot;和&quot;能不能画对因果&quot;分开考，才看得见视频生成器离世界模拟器还有多远。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>Flatten Temporal Video 保留了做因果推理所需的充分信息，因此 flatten 输入下的低分可以归因于模型不会推理，而不是表示丢了信息</strong>。整个显式侧的结论——尤其是&quot;开源生成器近乎崩溃&quot;——全部依赖这一点。如果 flatten 本身就毁掉了必要信息，那么这个分数测的是&quot;对 flatten 表示的鲁棒性&quot;，而不是因果感知能力。</p><p>它在实践中可能不成立的原因很具体。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1280</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">720</span></span></span></span> 的画布上摆 70 帧再加一块文本，每帧的有效分辨率降到百像素量级；很多因果线索（手的细微动作、小物体的位移、文字标识）在这个尺度上直接消失。更麻烦的是<strong>顺序歧义</strong>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">7</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span> 网格的时间顺序靠&quot;先行后列&quot;这个未言明的约定，而视频生成器从未在这种数据上训练过；一个模型完全可能正确理解了每一帧，却搞错了它们的时间关系。第三点，视频生成器的&quot;回答&quot;要通过生成一段视频来表达，这本身就是一个它没被训练过的任务格式——分数低可能只反映格式不匹配。</p><p>论文对此有明确的防御设计，这一点必须承认：作者专门用 MLLM 跑 Setting A（原生视频）与 Setting B（flatten 网格）的对照，其目的正是&quot;验证 flatten 策略是否保留了足够的因果推理信息&quot;。这是正确的对照设计。但它只能证明<strong>MLLM</strong> 在 flatten 下损失多少，不能直接推论视频生成器的损失同样大小——MLLM 见过大量图文混排与网格图，视频生成器没有。缺的证据是一个针对生成器的对照：例如用更少的帧（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">7</span></span></span></span> 那种单行排列）去做显式侧评测，看开源模型的分数是否显著回升。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不复现全部 1500 段视频与四个生成器的 API 调用，只测 §9 的表示充分性。</p><ul><li><strong>数据</strong>：从 Video-MME 里取 100 道题，覆盖六个域，优先选需要细粒度视觉线索的题目（涉及小物体、文字、手部动作）。</li><li><strong>实现</strong>：为每道题构造四种输入变体——(a) 原生视频（仅 MLLM 可用）；(b) 论文的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">7</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">70</span></span></span></span> 网格；(c) <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span> 的稀疏网格，单帧分辨率大幅提高；(d) 与 (c) 相同的帧但<strong>单行水平</strong>排列（消除换行歧义）。文本一律栅格化。</li><li><strong>测量</strong>：在两个 MLLM（一个小的如 Qwen3-VL-4B，一个强的如 Gemini-3-Flash）和一个开源视频生成器上分别跑四种变体，报告准确率。关键量是 <strong>(b) 与 (c)/(d) 的差值</strong>，以及这个差值在 MLLM 与生成器上是否量级相当。</li><li><strong>判据</strong>：若开源生成器在 (c) 或 (d) 下准确率显著回升（比如从接近 0 升到两位数），说明&quot;近乎崩溃&quot;至少部分是分辨率或顺序歧义造成的，论文的归因需要弱化。若四种变体下生成器都接近 0 而 MLLM 在 (b) 下已经可用，则支持论文的归因：问题在模型而不在表示。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的攻击针对<strong>评判器本身</strong>。CGDJ 的两条通道都由 Gemini-3-Pro 打分：显式侧判 Correct/Incorrect，隐式侧给 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 的连续分。同时，隐式侧数据的语义描述也由 Gemini-3-Pro 生成，并与视频一同注入生成器作为条件。这意味着同一个模型既写了题干的一部分，又当了裁判。</p><p>这构成一个可检验的替代解释：<strong>Perception-Prediction Gap 的一部分可能是评判器偏好造成的，而不是被测模型的真实能力差异</strong>。具体机制是，隐式侧的评分维度里有 Physical Validity（无闪烁、无物理违规）和 Semantic Alignment，这些是画质相关量，闭源模型在画质上天然占优；而显式侧考的是离散答案正确性，几乎不受画质影响。因此&quot;开源模型显式近零但隐式中等&quot;这一对比，有可能只是&quot;开源模型在一个宽松的连续尺度上拿到了中间分，在一个严格的二值判据上拿到了零分&quot;——两个通道的分数根本不可比，把它们的落差命名为 gap 需要额外论证。</p><p>反例实验的设计是：其一，做一次<strong>评判器交叉验证</strong>，用一个与出题无关的第三方评判器（例如换成 GPT-5 或人工）重跑隐式侧，看开源与闭源的相对排序和绝对分差是否保持。其二，做一次<strong>盲测校准</strong>，把 Gold Video 本身混进被评样本，看评判器给真值视频打多少分——如果真值也拿不到接近 1.0，说明该尺度存在系统性压缩，落差的解读要相应调整。其三，构造<strong>画质对照</strong>：把开源模型的输出做超分与去闪烁后处理再送评，若隐式分显著上升而显式分不变，则证实隐式通道对画质敏感。</p><p>另一类可预测失效场景是<strong>音频通道</strong>。作者用 whisper 转写音轨并纳入判定，这对 Sora-2、Veo-3.1 这类能生成音频的闭源模型是有利的——它们可以&quot;说出&quot;答案而不必&quot;画出&quot;答案。开源的 Wan-2.2 与 HunyuanVideo-1.5 若不生成语音，就永远拿不到这部分分数。论文自己观察到的 audio-visual misalignment（说得比画得准）恰恰说明音频通道贡献可观。因此显式侧的开源与闭源对比，需要一个&quot;仅视觉、屏蔽音频&quot;的消融才能干净地归因。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>CGDJ 的两条通道都是<strong>被动</strong>的：给一段前因，看模型说什么或画什么。这能测出相关性，但测不出因果——一个记住了&quot;玻璃杯掉地上会碎&quot;的模型，和一个理解了&quot;脆性材料在冲击下断裂&quot;的模型，在被动测试下表现相同。论文自己在 §1 说得很清楚：&quot;推理要求反事实与因果有效性&quot;，但整套评测里没有任何一处真的做了反事实操作。</p><p><strong>驱动局限</strong>：被动评测无法把因果理解与高频视觉关联分开，而这正是论文开篇提出的核心疑问。Perception-Prediction Gap 是一个有价值的诊断量，但它诊断的是两种能力的不匹配，不是因果性本身。</p><p><strong>可借鉴的相邻领域</strong>：因果推断里的 <strong>do-calculus 与干预分布</strong>，以及具身评测里的<strong>受控扰动</strong>协议。二者的共同点是不看模型在自然分布上的表现，而是主动改变一个变量再看输出是否按因果图预测的方向变化。视觉领域已有的对应工具是反事实图像编辑与物理参数可控的仿真器。</p><p><strong>新的 framing</strong>：把评测从&quot;预测后果&quot;改成&quot;<strong>响应干预</strong>&quot;。不再问&quot;接下来会发生什么&quot;，而是问&quot;如果我把这一个因改掉，结果该怎么变&quot;，并且要求模型的两个通道对同一次干预给出一致的响应。真正的因果理解会在干预下表现出<strong>结构化的、可预测方向的</strong>变化；记住的视觉关联则会要么不变（忽略干预），要么变化方向随机。</p><p><strong>第一个实验</strong>：从隐式侧的 Physion 与 Physics IQ 子集里挑出参数可控的场景（斜面角度、物体质量、摩擦系数、支撑点位置），对每个场景生成一组配对样本：原始前因，以及只改一个物理参数的干预版前因（可以直接用仿真器重渲染，保证只有一个变量变）。要求模型对两个版本分别生成后果，然后度量两件事——<strong>方向一致性</strong>（生成结果的变化方向是否与仿真真值一致，例如斜面变陡则滑落更快）与<strong>跨通道一致性</strong>（显式通道回答的&quot;会更快还是更慢&quot;是否与隐式通道画出来的一致）。如果模型在自然样本上得分不低，却在干预配对上方向一致性接近随机，那就直接支持了论文开篇的怀疑：合理的 rollout 来自记忆而非因果。反过来，如果方向一致性显著高于随机，就说明至少存在部分真实的因果结构，此时可以进一步按物理量类别定位它在哪些维度上成立。</p>',63)])])}const d=a(e,[["render",l]]);export{h as __pageData,d as default};
